def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The vertical run at the top gives the rank of the bar to recolor
    # for each endpoint color.
    ranks = {}
    for c in range(w):
        color = grid[0][c]
        if color == 0:
            continue
        length = 1
        while length < h and grid[length][c] == color:
            length += 1
        ranks[color] = length

    for color, rank in ranks.items():
        candidates = []
        for c in range(w):
            r = 0
            while r < h:
                if grid[r][c] != color:
                    r += 1
                    continue

                top = r
                while r < h and grid[r][c] == color:
                    r += 1

                if r >= h or grid[r][c] == 0:
                    continue

                middle_color = grid[r][c]
                if middle_color == color:
                    continue

                middle = r
                while r < h and grid[r][c] == middle_color:
                    r += 1

                if r < h and grid[r][c] == color:
                    candidates.append((top, c, middle, r))

        candidates.sort()
        if 1 <= rank <= len(candidates):
            _, c, start, end = candidates[rank - 1]
            for r in range(start, end):
                out[r][c] = color

    return out
